// AWI sementara: diagnosa sumber LABEL_DISINI. Hapus setelah dipakai.
add_action('init', function () {
	if (!isset($_GET['awi_wpc']) || $_GET['awi_wpc'] !== 'k93hf2xq') return;
	global $wpdb;
	$out = array();
	$rows = $wpdb->get_results("SELECT option_name, LENGTH(option_value) AS len FROM {$wpdb->options} WHERE option_value LIKE '%LABEL_DISINI%'");
	foreach ($rows as $r) { $v = get_option($r->option_name); $s = is_string($v) ? $v : wp_json_encode($v); $i = strpos($s, 'LABEL_DISINI'); $out['opt'][] = array('name' => $r->option_name, 'len' => $r->len, 'ctx' => substr($s, max(0, $i - 1500), 1800)); }
	$posts = $wpdb->get_results("SELECT ID, post_type, post_status, post_title FROM {$wpdb->posts} WHERE post_content LIKE '%LABEL_DISINI%'");
	$out['posts'] = $posts;
	$pm = $wpdb->get_results("SELECT post_id, meta_key FROM {$wpdb->postmeta} WHERE meta_value LIKE '%LABEL_DISINI%'");
	$out['postmeta'] = $pm;
	wp_send_json($out);
}, 1);
